'use strict';

const argon2 = require('@node-rs/argon2');
const crypto = require('node:crypto');

/**
 * Password hashing.
 *
 * Argon2id, which is memory-hard: an attacker with a GPU farm gains far less
 * advantage than against a purely iterative function. The parameters below
 * are the OWASP baseline — 19 MiB of memory, two passes — chosen because the
 * cost has to be borne on every login by officers using the portal on modest
 * hardware, and these settings stay under ~100ms on a typical server while
 * remaining expensive to attack in bulk.
 *
 * The salt is generated by the library and embedded in the hash string, so
 * the stored value is self-describing: changing these parameters later does
 * not invalidate existing hashes, and `needsRehash` detects the old ones.
 */
const OPTIONS = Object.freeze({
  algorithm: argon2.Algorithm.Argon2id,
  memoryCost: 19456, // KiB
  timeCost: 2,
  parallelism: 1,
});

async function hash(plaintext) {
  return argon2.hash(String(plaintext), OPTIONS);
}

/**
 * Verifies a password.
 *
 * Returns false rather than throwing on a malformed or absent hash, so an
 * account that has never had a password set behaves exactly like one with the
 * wrong password — the caller cannot tell the two apart from the outcome.
 */
async function verify(storedHash, plaintext) {
  if (!storedHash || !plaintext) {
    // Spend comparable time anyway, so "no password set" is not detectable by
    // how quickly the request comes back.
    await dummyWork();
    return false;
  }
  try {
    return await argon2.verify(storedHash, String(plaintext));
  } catch {
    return false;
  }
}

/** Burns roughly one hash's worth of time, to flatten the timing signal. */
async function dummyWork() {
  try {
    await argon2.hash(crypto.randomBytes(16).toString('hex'), OPTIONS);
  } catch {
    /* best effort */
  }
}

/** True when a stored hash was produced with weaker parameters. */
function needsRehash(storedHash) {
  if (!storedHash) return false;
  try {
    return argon2.needsRehash(storedHash, OPTIONS);
  } catch {
    return true;
  }
}

/**
 * Password policy.
 *
 * Length does more for strength than character-class rules, which mostly
 * push people towards `Password1!`. A 12-character floor plus a block on
 * obvious choices is the useful part; the rest is left to the operator's own
 * judgement and to rate limiting.
 */
const MIN_LENGTH = 12;
const MAX_LENGTH = 200;

const COMMON = new Set([
  'password', 'password1', 'password123', 'passw0rd', '123456789012',
  'qwertyuiop', 'administrator', 'letmein12345', 'welcome12345',
  'blueid123456', 'crossriver123', 'fisheries123',
]);

/**
 * @returns {{valid: boolean, problems: string[]}}
 */
function validate(password, { email, firstName, lastName } = {}) {
  const problems = [];
  const value = String(password || '');

  if (value.length < MIN_LENGTH) {
    problems.push(`Use at least ${MIN_LENGTH} characters`);
  }
  if (value.length > MAX_LENGTH) {
    problems.push(`Use at most ${MAX_LENGTH} characters`);
  }
  if (COMMON.has(value.toLowerCase())) {
    problems.push('That password is too common');
  }
  if (/^(.)\1+$/.test(value)) {
    problems.push('Do not use a single repeated character');
  }

  // A password containing the person's own name or email local-part is
  // guessable by anyone who knows them, which for a government officer is
  // a large group.
  const personal = [email?.split('@')[0], firstName, lastName]
    .filter((p) => p && p.length >= 3)
    .map((p) => p.toLowerCase());

  if (personal.some((p) => value.toLowerCase().includes(p))) {
    problems.push('Do not include your own name or email address');
  }

  return { valid: problems.length === 0, problems };
}

/** A temporary password for a newly created account, shown once. */
function generateTemporary() {
  // Base64url over 18 bytes gives 24 characters with no ambiguous separators.
  return crypto.randomBytes(18).toString('base64url');
}

module.exports = { hash, verify, needsRehash, validate, generateTemporary, MIN_LENGTH, OPTIONS };
